                    </div>
                </div>
            </Authorized>
            <NotAuthorized>
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Dispatcher Login</h5>
                        <p class="card-text">Sign in to access the dispatcher dashboard and manage shipments.</p>
                        <a href="Account/Login" class="btn btn-outline-primary">Sign In</a>
                    </div>
                </div>
            </NotAuthorized>
        </AuthorizeView>
    </div>
