namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServiceServer : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServiceServer(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await _db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await _db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
        => await _db.Shipments.FindAsync(id);

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        var shipment = await _db.Shipments.FindAsync(id);
        if (shipment != null)
        {
            shipment.Status = status;
            if (status == "Delivered")
                shipment.ActualDelivery = DateTime.UtcNow;
            await _db.SaveChangesAsync();
        }
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
        => await _db.Shipments.Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.ShippedDate).ToListAsync();
}
