namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Status { get; set; } = "Pending"; // Pending, InTransit, OutForDelivery, Delivered, Delayed
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> GetShipmentByIdAsync(int id);
    Task UpdateShipmentStatusAsync(int id, string status);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string email);
}

namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await _http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await _http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
        => await _http.GetFromJsonAsync<Shipment?>($"api/shipments/{id}");

    public async Task UpdateShipmentStatusAsync(int id, string status)
        => await _http.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
        => await _http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];
}

namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServiceServer : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServiceServer(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await _db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await _db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
        => await _db.Shipments.FindAsync(id);

    public async Task UpdateShipmentStatusAsync(int id, string status)
    {
        var shipment = await _db.Shipments.FindAsync(id);
        if (shipment != null)
        {
            shipment.Status = status;
            if (status == "Delivered")
                shipment.ActualDelivery = DateTime.UtcNow;
            await _db.SaveChangesAsync();
        }
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string email)
        => await _db.Shipments.Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.ShippedDate).ToListAsync();
}

namespace ShipmentTracker.Endpoints;

using ShipmentTracker.Client.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("{id:int}", async (int id, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByIdAsync(id);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).AllowAnonymous();

        group.MapGet("customer/{email}", async (string email, IShipmentService service) =>
            Results.Ok(await service.GetShipmentsByCustomerAsync(email)));

        group.MapPut("{id:int}/status", async (int id, StatusUpdate update, IShipmentService service) =>
        {
            await service.UpdateShipmentStatusAsync(id, update.Status);
            return Results.NoContent();
        });
    }

    public record StatusUpdate(string Status);
}

