                            <strong>Estimated Delivery:</strong> @(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Calculating...")
                            @if (s.ActualDelivery.HasValue)
                            {
                                <br /><strong>Delivered:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy HH:mm")
                            }
                        </p>
                        <a href="/track/@s.TrackingNumber" class="btn btn-sm btn-outline-primary">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? string.Empty;

        if (!string.IsNullOrEmpty(email))
        {
            try
            {
                shipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
            catch
            {
                shipments = [];
            }
        }
        isLoading = false;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "InTransit" => "bg-info",
        "OutForDelivery" => "bg-primary",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };
}
